讀取失敗時不進入迴圈，不會再次使用舊資料。

```cpp
#include <bits/stdc++.h>
using namespace std;
int main() {
    vector<int> f = {1, 2};
    while (f.back() < 100000000)
        f.push_back(f.back() + f[f.size() - 2]);
    int T, n;
    cin >> T;
    while (T--) {
        cin >> n;
        cout << n << " = ";
        bool start = false;
        for (int i = f.size() - 1; i >= 0; i--) {
            if (f[i] <= n) {
                cout << 1;
                n -= f[i];
                start = true;
            } else if (start)
                cout << 0;
        }
        cout << " (fib)\n";
    }
}
```

