#include <bits/stdc++.h>
using namespace std;
int main() {
    char c;
    bool open = true;
    while (cin.get(c)) {
        if (c == '"') {
            cout << (open ? "``" : "''");
            open = !open;
        } else
            cout << c;
    }
}
```

